UPDATE courses SET subtitle = 'الضرايب المصرية من الفاتورة لحد الإقرار، مع قصة كريم وشركة الكريم، ومحدّثة على قوانين 2026', intro = 'كورس عملي بيمشي معاك في الضرايب المصرية خطوة بخطوة، من أول ما الشركة تتسجل لحد ما تقف قدام لجنة الطعن. هنكمل مع كريم وشركة الكريم للتجارة والتوزيع، والشركة دلوقتي كبرت وبقت مكلّفة، وكل مستوى بيبدأ بمشكلة حقيقية بتقابل سارة المحاسبة وأ. مجدي مستشار الضرايب. هتتعلم الضريبة على القيمة المضافة، والخصم تحت حساب الضريبة، وضريبة المرتبات، وضريبة أرباح الأشخاص الاعتبارية، والأرباح الرأسمالية والتوزيعات، وضريبة المهن الحرة والضريبة العقارية، والفاتورة الإلكترونية والجزاءات والطعون. في كل مستوى هتلاقي الحساب الضريبي، والقيد المحاسبي حسب معايير المحاسبة المصرية، والمرجع القانوني لكل نقطة. قوانين الضرايب بتتعدل باستمرار، والمادة محدّثة حتى أكتوبر 2026 وبنحدّثها أول بأول. مادة تعليمية مستقلة، مش صادرة عن مصلحة الضرائب المصرية.', audience = 'المحاسبين حديثي التخرج والـ Junior، ومحاسبي الإقرارات، وأصحاب الشركات الصغيرة والمتوسطة، وأي حد عايز يشتغل في قسم الضرايب' WHERE slug = 'tax'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 1, 'كريم بقى مُكلَّف', 'الضريبة على القيمة المضافة: التسجيل وحد الـ 500 ألف، والمخرجات والمدخلات وشروط الخصم، وضريبة الواردات وتكلفة المخزون (معيار 2)، والتكليف العكسي على الخدمات المستوردة، والمناطق الحرة والتصدير، وتعديلات 2025 و2026 (المقاولات 14% والآلات 5%)، والإقرار الشهري ورد الرصيد الدائن.', 'مبيعات كريم عدّت نص مليون، وسارة بتقوله "لازم نتسجل". هل الـ 14% هتطلع من جيبه؟ ولا هو مجرد وسيط بين الزبون والمصلحة؟' FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 1, 'امتحان المستوى 1', 10, 50, 15 FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 2, 'الخصم من المنبع', 'نظام الخصم والتحصيل تحت حساب الضريبة: نسب الخصم 1% و3% و5% وحد الـ 300 جنيه، والخصم على أتعاب المهن الحرة، ونموذج 41 ومواعيده كل ربع سنة، والدفعات المقدمة، والإعفاءات اللي جات مع نظام المشروعات الصغيرة، والقيود المحاسبية للخصم عند الدفع والتحصيل.', 'كريم دفع لمورد 100 ألف، والمورد اتصل يسأل "فين الـ 1%؟". إمتى الشركة تخصم، ومين اللي بيورّد، والفلوس دي بتروح فين في الآخر؟' FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 2, 'امتحان المستوى 2', 10, 50, 15 FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 3, 'مرتبات آخر الشهر', 'الضريبة على المرتبات وما في حكمها: الشرائح السنوية وإزاي بتتلغي الشرائح الأقل للدخول العالية، والإعفاء الشخصي، والتأمينات والمزايا العينية والحوافز، والتسوية الشهرية والسنوية، ونماذج المرتبات، وقيود المرتبات في الدفاتر.', 'سارة لقت موظفين مرتبهم واحد وصافي القبض بتاعهم مختلف. الغلطة في الشيت؟ ولا في فهم الشرائح؟' FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 3, 'امتحان المستوى 3', 10, 50, 15 FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 4, 'الربح المحاسبي مش الربح الضريبي', 'ضريبة أرباح الأشخاص الاعتبارية: من صافي الربح المحاسبي للوعاء الضريبي، والمصروفات واجبة الخصم وغير واجبة الخصم، والإهلاك المحاسبي والضريبي، وحد خصم الفوايد، وترحيل الخسائر، والإقرار السنوي، والضريبة المؤجلة.', 'القوايم بتقول إن الشركة كسبت 2 مليون، والإقرار بيقول إن الضريبة على 2.6 مليون. منين جت الـ 600 ألف الزيادة؟' FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 4, 'امتحان المستوى 4', 10, 50, 15 FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 5, 'كريم بيستثمر', 'الأرباح الرأسمالية وتوزيعات الأرباح بعد تعديلات 2026: الأسهم المقيدة وغير المقيدة، وضريبة التوزيعات وإعفاء الشركات القابضة، والتصرف في العقارات، وضريبة الدمغة على تعاملات البورصة، والمعالجة المحاسبية للاستثمارات.', 'كريم اشترى أسهم وباع حتة أرض، والشركة وزعت أرباح لأول مرة. كل عملية فيهم ليها حكم ضريبي مختلف، وغلطة واحدة ممكن تتكلف كتير.' FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 5, 'امتحان المستوى 5', 10, 50, 15 FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 6, 'العيادة والمخزن', 'ضريبة المهن الحرة غير التجارية وتطبيقها على عيادة أخو كريم، والضريبة العقارية على المباني: الإعفاءات وحد الإعفاء للسكن والخصم للإقرار في الميعاد، ومعالجة الضريبة العقارية في الدفاتر.', 'أخو كريم فتح عيادة وفاكر إن الدكاترة مالهمش دعوة بالضرايب، وكريم جاله إخطار ضريبة عقارية على المخزن. الاتنين محتاجين أ. مجدي.' FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 6, 'امتحان المستوى 6', 10, 50, 15 FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 7, 'الإخطار وصل', 'الفاتورة والإيصال الإلكتروني، والدفاتر والسجلات والبطاقة الضريبية، والفحص، ومقابل التأخير والغرامات، ومراحل الطعن من اللجنة الداخلية لحد لجان الطعن والمحكمة، والمعالجة المحاسبية لفروق الفحص.', 'جواب من المصلحة بفروق فحص أكبر من أرباح سنة كاملة. كريم مش نايم، وأ. مجدي بيقوله: "اهدى، الطعن له مواعيد وله طريقة".' FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 7, 'امتحان المستوى 7', 10, 50, 15 FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'cumulative', 3, 'الامتحان التراكمي الأول (المستويات 1 إلى 3)', 20, 50, 40 FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'cumulative', 7, 'الامتحان الشامل (المستويات 1 إلى 7)', 20, 50, 40 FROM courses WHERE slug = 'tax'; INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 1), 'حد التسجيل الإلزامي في الضريبة على القيمة المضافة لأي نشاط عادي (مش مستورد ولا مصدّر ولا من سلع وخدمات الجدول) هو إن مبيعاته خلال الـ 12 شهر اللي قبل توصل:', '["500,000 جنيه","1,000,000 جنيه","100,000 جنيه","250,000 جنيه"]', 0, 'المادة 16 من القانون 67 لسنة 2016 حددت حد التسجيل بـ 500,000 جنيه من مبيعات السلع والخدمات الخاضعة والمعفاة خلال 12 شهر. (الوحدة 1.1)' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 1) AND body = 'حد التسجيل الإلزامي في الضريبة على القيمة المضافة لأي نشاط عادي (مش مستورد ولا مصدّر ولا من سلع وخدمات الجدول) هو إن مبيعاته خلال الـ 12 شهر اللي قبل توصل:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 1), 'لما مبيعات شركة توصل لحد التسجيل، لازم تقدّم طلب التسجيل خلال:', '["15 يوم من بلوغ الحد","60 يوم من بلوغ الحد","90 يوم من بلوغ الحد","30 يوم من بلوغ الحد"]', 3, 'طلب التسجيل بيتقدم خلال 30 يوم من تاريخ بلوغ حد الـ 500,000 جنيه. (الوحدة 1.1)' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 1) AND body = 'لما مبيعات شركة توصل لحد التسجيل، لازم تقدّم طلب التسجيل خلال:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 1), 'فاتورة بيع بمبلغ 22,800 جنيه شامل ضريبة 14%. أصل المبلغ قبل الضريبة:', '["19,608 جنيه","19,000 جنيه","22,800 جنيه","20,000 جنيه"]', 3, 'أصل المبلغ = 22,800 ÷ 1.14 = 20,000 جنيه. الضرب في 14% ثم الطرح غلط لأنه بيحسب ضريبة على الضريبة. (الوحدة 1.1)' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 1) AND body = 'فاتورة بيع بمبلغ 22,800 جنيه شامل ضريبة 14%. أصل المبلغ قبل الضريبة:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 1), 'فاتورة بيع بمبلغ 22,800 جنيه شامل ضريبة 14%. قيمة الضريبة اللي في الفاتورة:', '["3,192 جنيه","2,800 جنيه","2,000 جنيه","3,000 جنيه"]', 1, 'أصل المبلغ = 22,800 ÷ 1.14 = 20,000، والضريبة = 22,800 − 20,000 = 2,800 جنيه. رقم 3,192 جاي من ضرب المبلغ الشامل في 14% وده غلط. (الوحدة 1.1)' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 1) AND body = 'فاتورة بيع بمبلغ 22,800 جنيه شامل ضريبة 14%. قيمة الضريبة اللي في الفاتورة:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 1), 'مين من دول لازم يتسجل في القيمة المضافة من أول جنيه من غير حد تسجيل؟', '["شركة نظافة مبيعاتها 200,000 جنيه","محل بقالة مبيعاته 400,000 جنيه","تاجر بيستورد أجهزة بغرض الاتجار فيها","مكتب صيانة مبيعاته السنوية 300,000 جنيه"]', 2, 'المستورد بغرض الاتجار بيتسجل من غير حد. أما مقدم الخدمة العادي والتاجر المحلي فبيتسجلوا لما مبيعاتهم توصل 500,000 جنيه. (الوحدة 1.1)' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AN